//! Round-trip properties over generated files.
//!
//! The example tests in `write.rs` sample the round trip; these state
//! it. `parse(write(f))` describing the same device as `f` is the
//! central invariant of this crate — everything M1 does to a fuse map
//! depends on it — and the interesting failures live at edges an
//! example test would have to guess at: fuse counts that are not
//! multiples of eight, all-default and all-inverted devices, single-fuse
//! runs at the very end of the vector.
//!
//! Cases are generated by proptest and shrunk on failure, so a
//! counterexample arrives minimal rather than as a 2000-fuse haystack.

use decpld_diagnostics::FileId;
use decpld_jedec::{FuseVector, JedecFile, ParserMode, WriterStyle, parse, parse_with_mode, write};
use proptest::prelude::*;

const FILE: FileId = FileId(0);

/// A file with an arbitrary fuse vector, default state, and metadata.
fn any_jedec_file() -> impl Strategy<Value = JedecFile> {
    // Fuse counts deliberately include values that are not multiples of
    // eight, where the final partial word's padding bits decide whether
    // the checksum is right.
    (1usize..300, any::<bool>(), any::<bool>(), proptest::option::of(any::<bool>()))
        .prop_flat_map(|(count, default, has_header, security)| {
            (
                proptest::collection::vec(any::<bool>(), count),
                Just(default),
                Just(has_header),
                Just(security),
            )
        })
        .prop_map(|(states, default_fuse, has_header, security)| {
            let mut fuses = FuseVector::new(states.len() as u32, default_fuse);
            for (index, state) in states.iter().enumerate() {
                fuses.set(index as u32, *state).expect("in range by construction");
            }
            JedecFile {
                design_specification: if has_header {
                    "generated".to_owned()
                } else {
                    String::new()
                },
                fuses,
                default_fuse,
                notes: Vec::new(),
                security,
                fuse_checksum: None,
                transmission_checksum: None,
                unknown_fields: Vec::new(),
            }
        })
}

proptest! {
    #[test]
    fn canonical_output_round_trips(file in any_jedec_file()) {
        let text = write(&file, WriterStyle::Canonical).expect("writes");
        let reparsed = parse(&text, FILE).expect("our own output must parse").file;
        prop_assert!(
            file.describes_same_device_as(&reparsed),
            "round trip changed the file:\n{text}"
        );
    }

    #[test]
    fn compact_output_round_trips(file in any_jedec_file()) {
        // Compact only states fuses differing from the default, so it
        // exercises run detection: a bug in the run boundaries shows up
        // here and nowhere else.
        let text = write(&file, WriterStyle::Compact).expect("writes");
        let reparsed = parse(&text, FILE).expect("our own output must parse").file;
        prop_assert!(
            file.describes_same_device_as(&reparsed),
            "round trip changed the file:\n{text}"
        );
    }

    #[test]
    fn both_styles_describe_the_same_device(file in any_jedec_file()) {
        // Canonical states every fuse; compact states only the
        // surprising ones. They are different bytes and must be the same
        // device — this is what makes "compact" a style rather than a
        // lossy shortcut.
        let canonical = parse(&write(&file, WriterStyle::Canonical).unwrap(), FILE).unwrap().file;
        let compact = parse(&write(&file, WriterStyle::Compact).unwrap(), FILE).unwrap().file;
        prop_assert!(canonical.describes_same_device_as(&compact));
    }

    #[test]
    fn written_files_satisfy_their_own_checksums(file in any_jedec_file()) {
        // Strict mode verifies both checksums and requires the
        // transmission checksum to be present, so a successful strict
        // parse of our own output is the strongest statement available
        // that the writer computed them correctly.
        let text = write(&file, WriterStyle::Canonical).expect("writes");
        prop_assert!(parse_with_mode(&text, FILE, ParserMode::Strict).is_ok());
    }

    #[test]
    fn writing_is_idempotent(file in any_jedec_file()) {
        // `decpld jed canonicalize` run twice must not churn the file.
        let once = write(&file, WriterStyle::Canonical).expect("writes");
        let twice =
            write(&parse(&once, FILE).unwrap().file, WriterStyle::Canonical).expect("writes");
        prop_assert_eq!(once, twice);
    }

    #[test]
    fn the_fuse_checksum_is_independent_of_style(file in any_jedec_file()) {
        // The checksum covers the device, not the notation. Two styles
        // disagreeing would mean one of them is losing or inventing a
        // fuse.
        let canonical = parse(&write(&file, WriterStyle::Canonical).unwrap(), FILE).unwrap().file;
        let compact = parse(&write(&file, WriterStyle::Compact).unwrap(), FILE).unwrap().file;
        prop_assert_eq!(
            canonical.computed_fuse_checksum(),
            compact.computed_fuse_checksum()
        );
    }
}
